    fadeOutEnabled: false,
    fadeOutDurationMs: 0,
    pages: [
      {
        sceneId: "npc_dialog_sq_nila_shol",
        pageIndex: 0,
        label: "[ 닐라 숄 ]",
        text: "아우라 장부에서 물자가 새고 있어.\n빼돌린 배가 아군 신호를 달았더군.\n켓 미온한테 먼저 대조를 맡겨.",
        labelEn: "[ Nila Shol ]",
        textEn: "A supply cell is leaking from the Aura ledger.\nThe callsign is stamped like an ally.\nCross-check with Kett first.",
        imageAssetKey: "assets/images/npc/noname_char007.png",
        speakerNpcCaptainId: "npc_cpt_sq_nila_shol",
        viewMode: "ingame_dialog",
        textBoxPreset: "compact",
        imageScalePct: 100,
        actionLabel: null,
        actionLabelEn: null,
      },
      {
        sceneId: "npc_dialog_sq_nila_shol",
        pageIndex: 1,
        label: "[ 닐라 숄 ]",
        text: "나는 흔적만 쫓는 사람이야.\n아군 도장이 찍혔다고 믿지는 마.\n정체를 밝히는 건 켓의 몫이고.",
        labelEn: "[ Nila Shol ]",
        textEn: "I follow the tail only.\nDo not trust a report stamped friendly.\nKett opens the face.",
        imageAssetKey: "assets/images/npc/noname_char007.png",
        speakerNpcCaptainId: "npc_cpt_sq_nila_shol",
        viewMode: "ingame_dialog",
        textBoxPreset: "compact",
        imageScalePct: 100,
        actionLabel: null,
        actionLabelEn: null,
      },
      {
        sceneId: "npc_dialog_sq_nila_shol",
        pageIndex: 2,
        label: "[ 닐라 숄 ]",
        text: "매듭은 요새에서 짓겠어.\n지금은 장부부터 맞추고.\n대조가 끝나면 요새에서 보자.",
        labelEn: "[ Nila Shol ]",
        textEn: "I will close the testimony at the fort.\nMatch the ledger only for now.\nWhen the match is done I go to the fort.",
        imageAssetKey: "assets/images/npc/noname_char007.png",
        speakerNpcCaptainId: "npc_cpt_sq_nila_shol",
        viewMode: "ingame_dialog",
        textBoxPreset: "compact",
        imageScalePct: 100,
        actionLabel: null,
        actionLabelEn: null,
      }
    ],
